cards(E,'חמשת עקרונות OECD (2019) לבינה מלאכותית מהימנה',[('1 · תרומה לאנשים ולחברה','רווחה, קיימות וצמיחה מכילה','users'),('2 · חוק וזכויות אדם','שלטון החוק, פרטיות, שוויון וערכים דמוקרטיים','award'),('3 · שקיפות · Transparency','לדעת מתי מדובר ב-AI, מה מטרתו ומה גבולותיו','eye'),('4 · חוסן, בטיחות ואבטחה','פעולה יציבה, בטוחה ומאובטחת לאורך כל מחזור החיים','shield'),('5 · אחריותיות · Accountability','אחריות אנושית מוגדרת לכל החלטה משמעותית','user')],t2='OECD AI Principles — Trustworthy AI')
ld(E,'העקרונות הרביעי והחמישי',[('Robustness — חוסן','פעולה אמינה גם בקלט משתנה, תקלות, רעש ואי-ודאות','shield'),('Safety — בטיחות','צמצום סיכון לאנשים, תהליכים, רכוש וסביבה','warn'),('Security — אבטחה','הגנה מפני שימוש לרעה והתקפות','lock'),('Accountability — אחריותיות','האחריות על הארגון המפתח, הארגון המפעיל, ספקי השירות ובעלי העניין — לא על המערכת','users')],tip=('שימו לב','יש לבצע הערכת סיכונים לאורך כל מחזור החיים ולא רק בפיתוח, ולוודא שניתן לזהות מי אחראי לכל החלטה'))
sec(2,'2.6','Side Effects & Reward Hacking','תופעות לוואי ופריצת תגמול','תופעות לוואי בלתי רצויות ומניפולציות על מנגנוני התגמול',['Side Effects — תוצאה לא רצויה','Reward Hacking — ניצול מנגנון התגמול'],'warn')
steps(F,'Side Effects — כיצד הן נוצרות',[('1','מטרה לא שלמה','יעד צר או מדד חלקי'),('2','אילוצים חסרים','לא כל המגבלות העסקיות, האתיות והבטיחותיות הוגדרו'),('3','אופטימיזציה מקומית','שיפור המדד גם במחיר נזק צדדי'),('4','תופעת לוואי','תוצאה לא רצויה שלא הייתה חלק מהמטרה')],note=('הסיכון המרכזי','מערכת שמצליחה טכנית — אך פוגעת בהקשר הרחב (במשתמשים, בסביבה או במערכות אחרות)'))
ld(F,'Reward Hacking — פריצת תגמול',[('התגמול מוגדר באופן צר או חלקי','ואינו מייצג את המטרה האמיתית','target'),('המערכת מנצלת את ההגדרה','"קיצור דרך" במקום לפתור את הבעיה','route'),('הצלחה במדד בלבד','התוצאה נראית מוצלחת אך אינה משיגה את המטרה','warn')],tip=('סיכון מרכזי','אופטימיזציה של המדד במקום אופטימיזציה של הערך האמיתי — המערכת למדה בדיוק את מה שנמדד, ולא את מה שרצינו'))
vs(F,'Side Effects מול Reward Hacking',('Side Effects · נזק נלווה',[('מטרה','מושגת'),('בעיה','בתוצאות הלוואי'),('מקור','הקשר סביבתי שלא נשקל מספיק')]),('Reward Hacking · עקיפת המטרה',[('מטרה','לא מושגת באמת — רק המדד'),('בעיה','ניצול פונקציית התגמול'),('מקור','תגמול שאינו משקף את כוונת האדם')]),note=('ההבדל המרכזי','ב-Side Effects המטרה מושגת עם נזק לא רצוי; ב-Reward Hacking המדד מושג במקום המטרה'))
steps(F,'צמצום התופעות — יישור מטרות, דרישות, אילוצים ותגמול',[('1','מטרות','מה המערכת אמורה להשיג'),('2','דרישות','מה חייב להתקיים בפועל'),('3','אילוצים','במה אסור לפגוע בדרך'),('4','תגמול','כיצד המערכת מקבלת חיזוק'),('5','בקרה וניטור','גבולות פעולה ומעקב')],note=('הקשר לאיכות','איכות המערכת נמדדת לא רק בביצוע המשימה — אלא גם בדרך שבה היא נמנעת מנזק'))
sec(2,'2.7','Transparency, Interpretability & Explainability','שקיפות והסבריות','שלושה מושגים העוסקים ביכולת להבין ולהסביר את פעולת ה-AI — תומכים באמון, בבקרה ובקבלת החלטות אחראית',['Transparency · שקיפות','Interpretability · יכולת פירוש','Explainability · יכולת הסבר'],'eye')
cards(G,'שלושת המושגים',[('Transparency · שקיפות','זמינות המידע על פעולת המערכת: מה היא עושה, על בסיס אילו נתונים ומה מגבלותיה','eye'),('Interpretability · יכולת פירוש','המידה שבה אדם יכול להבין את הסיבה להחלטה — מה בקלט השפיע ואילו מאפיינים היו משמעותיים','search'),('Explainability · יכולת הסבר','היכולת להציג את הלוגיקה של המערכת והחלטותיה בשפה אנושית','info')],note=('הקשר ביניהם','Transparency מספקת את המידע, Interpretability מאפשרת להבין את המודל, ו-Explainability מתרגמת את ההבנה להסבר שימושי לאדם'))
cards(G,'Explainable AI (XAI)',[('ניהול סיכונים','זיהוי חריגות והחלטות לא צפויות לפני שהן משפיעות','warn'),('עמידה ברגולציה','תמיכה בדרישות שקיפות, בקרה, ביקורת ואחריות','award'),('שיפור המודלים','הבנת הסיבות להחלטות מסייעת לאתר הטיות וכשלים','sync'),('אמון משתמשים','שימוש אחראי במערכות AI','users')],lead=('הגדרה','תחום העוסק בפיתוח שיטות וכלים להבנה והסבר של האופן שבו מערכות AI מגיעות לתוצאותיהן'),note=('המסר','XAI הופך מודל ממערכת שמפיקה תוצאה — למערכת שניתן להבין, לבקר ולשפר'))
sec(2,'2.8','Safety and AI','בטיחות ובינה מלאכותית','הציפייה שמערכת מבוססת AI לא תגרום נזק לאנשים, לרכוש או לסביבה במהלך פעולתה',['תחבורה','פיננסים והחלטות רגישות','שירותים ציבוריים'],'shield')
ld(H,'אתגרי הבטיחות במערכות AI',[('מורכבות גבוהה','','sitemap'),('אי-דטרמיניזם ואופי הסתברותי','לא תמיד אותה תוצאה לכל מצב — כמה פתרונות אפשריים','random'),('למידה עצמית','ההתנהגות משתנה לאורך זמן','sync'),('חוסר שקיפות והסבר','','eye')],tip=('המשמעות','קשה לחזות התנהגות בכל מצב — בדיקות בטיחות מורכבות יותר מבתוכנה מסורתית'),note=('שימו לב','ככל שההשפעה על אדם או סביבה גבוהה יותר — כך גדלות דרישות הבטיחות'))
cards(H,'בטיחות כתוצאה של מאפייני איכות',[('חוסן','עמידות לשיבושים ולמצבי קצה','shield'),('דיוק','הפחתת טעויות בהחלטות ובתחזיות','target'),('יציבות','התנהגות עקבית לאורך זמן','check'),('צפיות','יכולת לחזות מה צפוי לקרות','eye')],note=('שימו לב','בטיחות אינה מאפיין בודד — חולשה באחד המאפיינים עלולה להגדיל סיכון'))
steps(H,'בטיחות לאורך תהליך הפיתוח',[('1','הגדרת צורך','זיהוי סיכוני בטיחות כבר בתחילת הדרך'),('2','איסוף נתונים','בדיקת איכות, הטיות וייצוגיות'),('3','אימון מודל','בקרה על למידה לא רצויה'),('4','פריסה','הגבלות שימוש, ניטור והחזרת שליטה לאדם'),('5','ניטור ושיפור','מעקב, תיקון כשלים ועדכון')],note=('שימו לב','בטיחות אינה שלב חד-פעמי בסוף הפיתוח — היא דרישה מתמשכת לאורך כל מחזור החיים'))
